<x-admin-layout :title="$district->name"><nav class="admin-breadcrumb"><a href="{{ route('staff.districts.index') }}">Districts</a><span>/</span><span>{{ $district->name }}</span></nav><div class="review-heading"><div><span class="admin-status admin-status--{{ $district->workflow_status }}">{{ str($district->workflow_status)->replace('_',' ')->title() }}</span><h1>{{ $district->name }}</h1><p>{{ $district->region->name }} Region · Capital: {{ $district->capital ?? 'Not recorded' }}</p></div><dl><div><dt>Version</dt><dd>{{ $district->version }}</dd></div><div><dt>Opportunities</dt><dd>{{ $district->opportunities_count }}</dd></div><div><dt>SLA due</dt><dd @class(['is-overdue'=>$district->sla_due_at?->isPast()])>{{ $district->sla_due_at?->format('j M Y, H:i') ?? 'Not active' }}</dd></div></dl></div><div class="review-layout"><article class="review-content"><section><h2>District profile</h2><div class="review-facts"><div><span>Region capital</span><strong>{{ $district->region->capital ?? 'Not recorded' }}</strong></div><div><span>District capital</span><strong>{{ $district->capital ?? 'Not recorded' }}</strong></div><div><span>Readiness score</span><strong>{{ $district->readiness_score ?? 'Not assessed' }}</strong></div><div><span>Population</span><strong>{{ $district->population ? number_format($district->population) : 'Not recorded' }}</strong></div><div><span>Area</span><strong>{{ $district->area_sq_km ? number_format((float)$district->area_sq_km,2).' km²' : 'Not recorded' }}</strong></div><div><span>Boundary</span><strong>{{ $district->boundary ? 'Loaded' : 'Awaiting approved GeoJSON' }}</strong></div></div></section><section><h2>Workflow history</h2><ol class="workflow-timeline">@forelse($district->workflowEvents as $event)<li><i aria-hidden="true"></i><div><strong>{{ str($event->action)->replace('_',' ')->title() }}</strong><span>{{ str($event->from_status)->replace('_',' ')->title() }} → {{ str($event->to_status)->replace('_',' ')->title() }}</span><small>{{ $ev